    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // select table\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure select table\n"
    "    parameters $Table\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | stageB\n"
    "\n"
    "  stage stageB on all partitions :\n"
    "    scan $Table | stageC\n"
    "\n"
    "  stage stageC on origin :\n"
    "    output | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // tableScan\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure tableScan\n"
    "    parameters $table\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | stageB\n"
    "\n"
    "  stage stageB on all partitions :\n"
    "    scan $table | stageC\n"
    "\n"
    "  stage stageC on origin :\n"
    "    output | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // truncate\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure truncate\n"
    "    tags <lowMemory>\n"
    "    parameters $table\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | stageB\n"
    "\n"
    "  stage stageB on all partitions :\n"
    "    truncateTable $table | stageC\n"
    "\n"
    "  stage stageC on origin :\n"
    "    output | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* load related procedures                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\"  start::defProc_Load\" .verbose\n"
    "\n"
    ": start::defProc_Load\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // load\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure load\n"
    "    parameters $table $file\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "        start\n"
    "      | pulse once\n"
    "      | chunk $file       // read chunks of file => (seekOffset)\n"
    "      | rdCsvChunk $file  // (seekOffset) => (csvBuffer)\n"
    "      | stageB robin\n"
    "\n"
    "    stage stageB on all partitions on origin :\n"
    "        toRow $table      // pf    (csvBuffer) => (rowBuffer w row+hash)\n"
    "      | toPtnRow          //    pf (rowBuffer) => (ptn rowBuffer)\n"
    "    //| toBktRow          //       (rowBuffer) => (bkt rowBuffer)\n"
    "      | toNstRow          //       (rowBuffer) => (nst rowBuffer)\n"
    "      | toPtnCrw          //       (rowBuffer) => (ptn crwBuffer)\n"
    "    //| toBktCrw          //       (rowBuffer) => (bkt crwBuffer)\n"
    "      | stageC hashcast\n"
    "\n"
    "    stage stageC on all partitions :\n"
    "        insert $table     // (crwBuffer) inserted into table\n"
    "      | stageD\n"
    "\n"
    "    stage stageD on origin :\n"
    "        progress 'Load'\n"
    "      | output\n"
    "      | toStatDemon\n"
    "      | sink\n"
    "      | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // load (bucket)\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure load_bkt\n"
    "    parameters $table $file\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "        start\n"
    "      | pulse once\n"
    "      | chunk $file       // read chunks of file => (seekOffset)\n"
    "      | rdCsvChunk $file  // (seekOffset) => (csvBuffer)\n"
    "      | stageB robin\n"
    "\n"
    "    stage stageB on all partitions on origin :\n"
    "        toRow $table      // pf    (csvBuffer) => (rowBuffer w row+hash)\n"
    "      | toBktRow          //       (rowBuffer) => (bkt rowBuffer)\n"
    "      | toNstRow          //       (rowBuffer) => (nst rowBuffer)\n"
    "      | toBktCrw          //       (rowBuffer) => (bkt crwBuffer)\n"
    "      | stageC hashcast\n"
    "\n"
    "    stage stageC on all partitions :\n"
    "        insert $table     // (crwBuffer) inserted into table\n"
    "      | stageD\n"
    "\n"
    "    stage stageD on origin :\n"
    "        progress 'Load'\n"
    "      | output\n"
    "      | toStatDemon\n"
    "      | sink\n"
    "      | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // dfload\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure dfload\n"
    "    parameters $table $file\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "\n"
    "    start              |\n"
    " \n"
    "    pulse once    |\n"
    "\n"
    "    stageB\n"
    "\n"
    "  stage stageB on all nodes :\n"
    "\n"
    "    chunk $file        | // read chunks of file, produce (seekOffset) =>\n"
    "    // dump seekOffsets 1 |\n"
    "\n"
    "    rdCsvChunk $file   | // (seekOffset) => (csvBuffer)\n"
    "    // dump csvBuffer 0   |\n"
    "\n"
    "    stageC localRobin\n"
    "\n"
    "  stage stageC on all partitions :\n"
    "\n"
    "    toRow $table       | // (csvBuffer)  => (rowBuffer)\n"
    "    // dump rowBuffer 1   |\n"
    "\n"
    "    toPtnRow           | // (rowBuffer)  => (rowBuffer 'ptn)\n"
    "    // dump rowBuffer 1   |\n"
    "\n"
    "    toNstRow           | // (rowBuffer)  => (rowBuffer 'nst)\n"
    "    //dump rowBuffer 1   |\n"
    "\n"
    "    toHshCrw           | // (rowBuffer)  => (crwBuffer 'hsh)\n"
    "    //dump rowBuffer 1   |\n"
    "\n"
    "    stageD hashcast\n"
    "\n"
    "  stage stageD on all partitions :\n"
    "\n"
    "    //eatSome |\n"
    "\n"
    "    insert $table | // (crwBuffer) inserted into table\n"
    "\n"
    "    stageE\n"
    "\n"
    "  stage stageE on origin :\n"
    "\n"
    "    progress 'Load'    |\n"
    "\n"
    "    toStatDemon        |\n"
    "\n"
    "    sink               |\n"
    "\n"
    "    stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // dload\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure dload\n"
    "    parameters $table\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "        start\n"
    "      | pulse once\n"
    "      | eachPath \n"
    "      |   toDfload $table\n"
    "      | callPipeline\n"
    "      | waitPipeline\n"
    "      | sink\n"
    "      | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* api related procedures                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\"  start::defProc_Api\" .verbose\n"
    "\n"
    ": start::defProc_Api\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // getRows\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure getRows\n"
    "    parameters $Table\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start         |\n"
    "    pulse once |\n"
    "    stageB\n"
    "\n"
    "  stage stageB on all partitions :\n"
    "    scan $Table   |\n"
    "    crwToRow      |\n"
    "    stageC\n"
    "\n"
    "  stage stageC on origin :\n"
    "    output        |\n"
    "    sink          |\n"
    "    stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // putRows\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure putRows\n"
    "    parameters $Table\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start         |\n"
    "    pulse once |\n"
    "    input         |\n"
    "    stageB robin\n"
    "\n"
    "  stage stageB on all partitions on origin :\n"
    "    toRow $Table  |\n"
    "    toPtnRow      |\n"
    "    toNstRow      |\n"
    "    toHshCrw      |\n"
    "    stageC hashcast\n"
    "\n"
    "  stage stageC on all partitions :\n"
    "    insert $Table |\n"
    "    stageD\n"
    "\n"
    "  stage stageD on origin :\n"
    "    sink          |\n"
    "    stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* file related procedures                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\"  start::defProc_File\" .verbose\n"
    "\n"
    ": start::defProc_File\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // copy file\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure copyFile\n"
    "    parameters $FileIn $FileOut\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | catFile $FileIn | wrFile $FileOut | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // copyFile \"/Users/Shared/tpch/SF1/nation.csv\" \"/Users/Shared/tpch/SF1/nation_COPY.csv\" ;\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // list file\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure listFile\n"
    "    parameters $File\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "      start | pulse once | catFile $File | output | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // listFile \"/Users/Shared/tpch/SF1/nation.csv\" ;\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // xyz file\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure xyzFile\n"
    "    parameters $Table $File $Ntimes\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "      start\n"
    "        | pulse once\n"
    "//        | catFile $File\n"
    "        | rdCsvCyclic $File $NTimes\n"
    "        | toRow $Table\n"
    "        | toPtnRow\n"
    "        | toNstRow\n"
    "        | stageB hashcast\n"
    "\n"
    "    stage stageB on all partitions :\n"
    "      noop\n"
    "        | stageC\n"
    "\n"
    "    stage stageC on origin :\n"
    "      output\n"
    "        | sink\n"
    "        | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // xyzFile nation \"/Users/Shared/tpch/SF1/nation.csv\" 3 ;\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // cycle read file\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure cyclicRdFile\n"
    "    parameters $FileIn $NTimes\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "      start | pulse once |\n"
    "        rdCsvCyclic $FileIn $NTimes | output | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "// cyclicRdFile \"/Users/Shared/tpch/SF1/nation.csv\" 3 ;\n"
    "// cyclicRdFile \"/Users/Shared/tpch/SF1/supplier.csv\" 3 ;\n"
    "// cyclicRdFile \"/Users/Shared/tpch/SF1/part.csv\" 3 ;\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* elasticity procedures                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\"  start::defProc_Elasticity\" .verbose\n"
    "\n"
    ": start::defProc_Elasticity\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // add node\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure add node\n"
    "    parameters $NodeNm $IpAddr $PortNo\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "\n"
    "      start\n"
    "        | pulse once\n"
    "        | stageB\n"
    "\n"
    "    stage stageB on all nodes :\n"
    "\n"
    "      addNode $NodeNm $IpAddr $PortNo\n"
    "        | stageC\n"
    "\n"
    "    stage stageC on origin :\n"
    "      output\n"
    "        | sink\n"
    "        | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // adjust partitions\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure adjust partitions\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "\n"
    "      start\n"
    "        | pulse once\n"
    "        | stageB\n"
    "\n"
    "    stage stageB on all nodes :\n"
    "\n"
    "      adjustPtns\n"
    "        | stageC\n"
    "\n"
    "    stage stageC on origin :\n"
    "      output\n"
    "        | sink\n"
    "        | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // remove node\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure remove node\n"
    "    parameters $NodeNm\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "\n"
    "      start | pulse once\n"
    "            | removeNode $NodeNm\n"
    "            | output\n"
    "            | sink\n"
    "            | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // spawn node\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure spawn node\n"
    "    parameters $NodeNm\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "\n"
    "      start | pulse once\n"
    "            | spawnNode $NodeNm\n"
    "            | output\n"
    "            | sink\n"
    "            | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "   // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "   // prototype get meta object\n"
    "\n"
    "    STD_PATH\n"
    "    \"\n"
    "    procedure pgetMeta\n"
    "      parameters $TableNm\n"
    "    begin\n"
    "\n"
    "      stage stageA on origin :\n"
    "        start | pulse once | pmetaGet $TableNm | stageB hashed\n"
    "\n"
    "      stage stageB on all nodes :\n"
    "        pmetaSend | stageC\n"
    "\n"
    "      stage stageC on origin :\n"
    "        pmetaRecv | output | sink | stageA\n"
    "\n"
    "    end ;\n"
    "    \"\n"
    "    api::addProcedure\n"
    "\n"
    "     // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "     // prototype assertGrid\n"
    "\n"
    "      STD_PATH\n"
    "      \"\n"
    "      procedure assertGrid\n"
    "      begin\n"
    "\n"
    "        stage stageA on origin :\n"
    "          start | pulse once | gridGet | stageB hashed\n"
    "\n"
    "          // prototyping, on the same machine\n"
    "          //stage stageB on all nodes :                gridSend | gridRecv | stageC\n"
    "          //stage stageC on origin :                noop | sink | stageA\n"
    "\n"
    "        stage stageB on all nodes :\n"
    "              gridSend | stageC\n"
    "\n"
    "        stage stageC on origin :\n"
    "              gridRecv | output | sink | stageA\n"
    "\n"
    "      end ;\n"
    "      \"\n"
    "      api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // dump grid info\n"
    "\n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure dumpGrid\n"
    "  begin\n"
    "    stage stageA on origin :\n"
    "      start | pulse once | dumpGridInfo  | output | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "   // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "   //  dump table meta info\n"
    "\n"
    "    STD_PATH\n"
    "    \"\n"
    "    procedure dumpMeta\n"
    "      parameters $TableNm\n"
    "    begin\n"
    "      stage stageA on origin :\n"
    "        start | pulse once | dumpMetaInfo $TableNm  | output | sink | stageA\n"
    "\n"
    "    end ;\n"
    "    \"\n"
    "    api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get bucket object, for prototyping, use two table params $TableNm1 -> $TableNm2\n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure getBucket\n"
    "    parameters $TableNm1 $TableNm2\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "      start | pulse once | bucketGet $TableNm1 | stageB\n"
    "\n"
    "    stage stageB on all partitions :\n"
    "      bucketSend $TableNm1 | stageC\n"
    "\n"
    "    stage stageC on all partitions :\n"
    "      insert $TableNm2 | stageD\n"
    "\n"
    "    stage stageD on origin :\n"
    "       sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get meta object\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure getMeta\n"
    "    parameters $TableNm\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "      start | periodic once | metaGet $TableNm | stageB hashcast\n"
    "\n"
    "    stage stageB on all nodes :\n"
    "      metaSend | metaRecv | stageC\n"
    "\n"
    "    stage stageC on origin :\n"
    "      //metaRecv | output | sink | stageA\n"
    "      noop | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* steady state related procedures                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\"  start::defProc_SteadyState\" .verbose\n"
    "\n"
    ": start::defProc_SteadyState\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // steady state test 1\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure steadyState_1\n"
    "    parameters $Table $File $NTimes\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "      start\n"
    "        | pulse once\n"
    "        //|  rdCsvCyclic $File $NTimes\n"
    "        | catFile $File\n"
    "        | toRow $Table\n"
    "        | toPtnRow\n"
    "        | stageB hashcast\n"
    "\n"
    "    stage stageB on all partitions :\n"
    "      noop\n"
    "      //insdel $Table\n"
    "        | stageC\n"
    "\n"
    "    stage stageC on origin :\n"
    "      output\n"
    "        | sink\n"
    "        | stageA\n"
    "\n"
    "  end ;\n"
    "\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // steady state test 2\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure steadyState_2\n"
    "    parameters $Table $File $NTimes\n"
    "  begin\n"
    "\n"
    "    stage stageA on origin :\n"
    "      start\n"
    "        | pulse once\n"
    "        //|  rdCsvCyclic $File $NTimes\n"
    "        | catFile $File\n"
    "        | toRow $Table\n"
    "        | toPtnRow\n"
    "        | stageB hashcast\n"
    "\n"
    "    stage stageB on all partitions :\n"
    "      //noop\n"
    "      insdel $Table\n"
    "        | stageC\n"
    "\n"
    "    stage stageC on origin :\n"
    "      output\n"
    "        | sink\n"
    "        | stageA\n"
    "\n"
    "  end ;\n"
    "\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // steady state test 3\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure steadyState_3\n"
    "   parameters $Table $File $NTimes\n"
    "  begin\n"
    "\n"
    "   stage stageA on origin :\n"
    "\n"
    "     start |\n"
    "\n"
    "     pulse once |\n"
    "\n"
    "     rdCsvCyclic $File $NTimes |\n"
    "\n"
    "     stageB robin\n"
    "\n"
    "\n"
    "   stage stageB on all partitions on origin  :\n"
    "\n"
    "     toRow $Table |\n"
    "\n"
    "     toPtnRow |\n"
    "\n"
    "     //toNstRow |\n"
    "\n"
    "     //toHshCrw |\n"
    "\n"
    "     stageC hashcast\n"
    "\n"
    "\n"
    "   stage stageC on all partitions :\n"
    "\n"
    "     insdel $Table |\n"
    "\n"
    "     stageD\n"
    "\n"
    "\n"
    "   stage stageD on origin :\n"
    "\n"
    "     //output |\n"
    "\n"
    "     sink |\n"
    "\n"
    "     stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* unload/realod related procedures                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\"  start::defProc_UnloadReload\" .verbose\n"
    "\n"
    ": start::defProc_UnloadReload\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // unload\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure unload\n"
    "    parameters $Table $File\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | stageB\n"
    "\n"
    "  stage stageB on all partitions :\n"
    "    scan $Table | stageC\n"
    "\n"
    "  stage stageC on origin :\n"
    "    wrFile $File | stageD\n"
    "\n"
    "  stage stageD on origin :\n"
    "    sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // /time unload LineItem \"/tmp/lineitem.crw\" ;\n"
    "\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // reload\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure reload\n"
    "    parameters $Table $File\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | rdCrwFile $File | stageB\n"
    "\n"
    "  stage stageB on all partitions :\n"
    "    insert $Table | stageC\n"
    "\n"
    "  stage stageC on origin :\n"
    "    sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // /time reload LineItem \"/tmp/lineitem.crw\" ;\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // reorder table\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure reorder\n"
    "    parameters $table1 $table2 $predicate\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | emitStreamDef $Table1 | stageB\n"
    "\n"
    "  stage stageB on all nodes :\n"
    "    createTable $table2 | stageC\n"
    "\n"
    "  stage stageC on all partitions :\n"
    "    fetch $table1 $predicate | insert $table2 | stageD\n"
    "\n"
    "  stage stageD on origin :\n"
    "    sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forget/rebalance related procedures                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\"  start::defProc_forgetRebalance\" .verbose\n"
    "\n"
    ": start::defProc_ForgetRebalance\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // forgetNode\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure forgetNode\n"
    "    parameters $NodeNm $etc\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | stageB\n"
    "\n"
    "  stage stageB on all nodes :\n"
    "    stageC\n"
    "\n"
    "  stage stageC on origin :\n"
    "    output | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    " ;\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // rebalance\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure rebalance\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | stageB\n"
    "\n"
    "  stage stageB on all nodes :\n"
    "    stageC\n"
    "\n"
    "  stage stageC on origin :\n"
    "    output | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 1 CONSTANT se_procedures.sen "_Stz;
