  // munge of [2] OP_stats.sen

  gszaMungedText[2] =
    "\" munged OP_stats.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_stats.sen -- Operator stats                                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_stats.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_M_START ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": stats_StartMarker \\handler\n"
    "\n"
    "  PipeIn[].pipeOut\n"
    "\n"
    "  \"+++ +++ +++\" .\n"
    "\n"
    "//  C_TDEF_LOCKSTATS word::find if\n"
    "//    C_TDEF_LOCKSTATS Path[].pushNamedTableFolder\n"
    "//    Path[].toStr .\n"
    "//    C_TDEF_LOCKSTATS find execute to Table[]\n"
    "//    StreamDefLft[].new\n"
    "//    StreamDefLft[].asStr .\n"
    "//    nullptr to Operand[]\n"
    "//  then\n"
    "/*\n"
    "  // find the __lockStats table\n"
    "  C_TDEF_LOCKSTATS op__tableDef_infoSet assert\n"
    "\n"
    "  // create a new streamDef\n"
    "  infoSetTable[] StreamDefLft[].new\n"
    "\n"
    "  //StreamDefLft[].asStr .\n"
    "  Expressions::lockSample to operandC[]\n"
    "  OperandC[].pipeOut\n"
    "*/\n"
    "\n"
    "  // find the __lockStats table\n"
    "  C_TDEF_LOCKSTATS op__tableDef_infoSet assert\n"
    "\n"
    "  // create an infoSet operand\n"
    "  infoSetTable[] InfoSet[].new\n"
    "\n"
    "  // add lock  to the infoSet\n"
    "  infoSetTable[] InfoSet[].addLockStats assert\n"
    "\n"
    "  // pipeout the infoset\n"
    "  InfoSet[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_M_EXITING ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": stats_Exiting \\handler\n"
    "\n"
    "  // find the __lockStats table\n"
    "  C_TDEF_LOCKSTATS op__tableDef_infoSet assert\n"
    "\n"
    "  // create an infoSet operand\n"
    "  infoSetTable[] InfoSet[].new\n"
    "\n"
    "  // add lock to the infoSet\n"
    "  infoSetTable[] InfoSet[].addLockStats assert\n"
    "\n"
    "  // pipeout the infoset\n"
    "  InfoSet[].pipeOut\n"
    "\n"
    "  ZK_M_EXITING_handler // calling op_loop exits\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* stats request                                      (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": stats_req \\operator\n"
    "\n"
    "  _lu_initialise_\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: stats_StartMarker ZK_M_START op[].handler!\n"
    "  find: stats_Exiting     ZK_M_EXITING  op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  \"*** stats EXITS\" .\n"
    "  _lu_finalise_\n"
    "  \n"
    "  op__retires\n"
    "  \n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: stats :: stats ;\n"
    "\n"
    ": stats_cmdTags _cmdTags tagCopy: op_tags\n"
    "  tags{ <cmdDesc> = \"--desc for op--\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 2 CONSTANT OP_stats.sen "_Stz;
