  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [4] se_folder.sen

  gszaMungedText[4] =
    "\" munged se_folder.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* se_folder.sen -- folder related words                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" se_folder.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder.hasRef ( word )\n"
    "\n"
    "  dup execute dic.ref\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check dic is empty                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder.isEmpty ( pFolder -- true | error false )\n"
    "\n"
    "  dup execute dic.wordCount if EC_FOLDER_NOT_EMPTY false exit_rt then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check folder is not in use                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder.notUsed ( pFolder -- true | error false )\n"
    "\n"
    "  folder.hasRef if EC_FOLDER_IN_USE false exit_rt then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get current folder                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Folder[] ( -- )\n"
    "\n"
    "  Path[].depth 1 - Path[].pick\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get current folder contents                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Folder[].contentStr ( -- s )\n"
    "\n"
    "  \"\"\n"
    "  Folder[] dic.lastWord dup iterate\n"
    "\n"
    "    object@ word.name@ str.cat\n"
    "\n"
    "    \" \" str.cat\n"
    "\n"
    "    object@ word.prev object!\n"
    "\n"
    "  next\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make new folder given name                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder::makeFolder params| sFolderNm |\n"
    "\n"
    "dicLock.grabwrite\n"
    "\n"
    "  find: \\folder locals| pwFolderCatg |\n"
    "\n"
    "  sFolderNm dic::new locals| pFolder |\n"
    "\n"
    "  sFolderNm word::new locals| pwFolder |\n"
    "\n"
    "  pwFolderCatg pFolder pwFolder word.cppObject!\n"
    "\n"
    "dicLock.dropwrite\n"
    "\n"
    "  args.verbose if\n"
    "    pwFolder word.name@\n"
    "    Path[].toStr\n"
    "      \"Created folder %v/%v\" .printf\n"
    "  then\n"
    "\n"
    "  //pwFolder word.see\n"
    "\n"
    "  pwFolder // returns:\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a sub-folder under given folder                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder::makeSubFolder params| pFolder sSubFolderNm |\n"
    "\n"
    "  pFolder Path[].pushFolder\n"
    "\n"
    "    find: \\folder\n"
    "    sSubFolderNm folder::makeFolder execute dic.kind!\n"
    "\n"
    "  Path[].popFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove folder                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder::remove params| sFolderNm |\n"
    "\n"
    "  sFolderNm find locals| pWord |\n"
    "\n"
    "  pWord not if exit_rt then\n"
    "\n"
    "  pWord word.object@ locals| pDic |\n"
    "  0 pWord word.object!\n"
    "\n"
    "  pDic dic.delete\n"
    " \n"
    "  sFolderNm :forget\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test name is a known table                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": name::isSubFolder params| sTableNm | ( t | f )\n"
    "\n"
    "  sTableNm Folder[].findSymbol locals| pwWord |\n"
    "\n"
    "  pwWord not if false exit then\n"
    "\n"
    "  pwWord word.category@ find: \\folder equal\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list all words (long form) in the current dictionary                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": symbols \\prompt\n"
    "\n"
    "  Path[].toStr .put \"::\" .put .\\n\n"
    "\n"
    "  Folder[] dic.lastWord\n"
    "  begin dup while\n"
    "    dup word.name@ .put \" \" .put dup word.category@ word.name@ .put .\\n\n"
    "    word.prev\n"
    "  repeat\n"
    "  discard\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 4 CONSTANT se_folder.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

