    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_M_LEAVE ...                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": compiler_LeaveMarker \\handler\n"
    "\n"
    "  // save the pipein in streamSet[]\n"
    "  StreamSet[].isNull not assert\n"
    "  StreamSet[].pipeout\n"
    "\n"
    "  ZK_M_LEAVE_handler\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_D_STREAMSET ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": compiler_StreamSet \\handler\n"
    "\n"
    "  // save the pipein in streamSet[]\n"
    "  Pipein[]\\clear to StreamSet[]\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* common code for handling plan operand ...                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": compiler_PlanOperand ( sOperatorName )\n"
    "\n"
    "  params| sOperatorName |\n"
    "\n"
    "  PlanOperand[].isNull if\n"
    "\n"
    "    // We got an error, but were we going to do an explain?\n"
    "    StreamSet[].isNull not if\n"
    "      StreamSet[].delete\n"
    "    then\n"
    "\n"
    "    op__cmdErrOut\n"
    "\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // no error, delete the infoset\n"
    "  InfoSet[].delete\n"
    "\n"
    "  // does the sql have an explain ?\n"
    "  PlanOperand[] sOperatorName sqlCompiler::hasExplain if\n"
    "\n"
    "    // execute explain for this operator\n"
    "    PlanOperand[] sOperatorName sqlCompiler::doExplain\n"
    "\n"
    "    // pipeout explain\n"
    "    StreamSet[].pipeout\n"
    "\n"
    "    LogicUnit[].compilerToExit if\n"
    "      PlanOperand[].delete\n"
    "      Marker[].newLeaveMarker\n"
    "      Marker[].pipeout\n"
    "      true\n"
    "      exit\n"
    "    then\n"
    "\n"
    "  then\n"
    "\n"
    "  PlanOperand[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

