  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [57] OP_listTenants.sen

  gszaMungedText[57] =
    "\" munged OP_listTenants.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_listTenants.sen -- Operator list tenants                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_listTenants.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lsten_action\n"
    "\n"
    "  0 locals| errorCode |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // should be in the tenants folder\n"
    "  Folder[].checkIsTenants not if\n"
    "    to errorCode\n"
    "    errorCode op__execErr\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // find the __ table\n"
    "  <streamDef> op__tableDef_streamSet assert\n"
    "\n"
    "  // create a new streamDef\n"
    "  streamSetTable[] StreamDefLft[].new\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  StreamDefLft[].pipeOut\n"
    "\n"
    "  // create an infoSet operand\n"
    "  streamSetTable[] StreamSet[].new\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // insert a row in teh infoSet for each word\n"
    "\n"
    "  Folder[] dic.lastWord dup\n"
    "  iterate                          // setup iteration of words\n"
    "    object@ word.name@\n"
    "    streamSetTable[] StreamSet[].addListContents  not if\n"
    "      StreamSet[].pipeOut\n"
    "      streamSetTable[] streamSet[].new\n"
    "      object@ word.name@\n"
    "      streamSetTable[] StreamSet[].addListContents assert\n"
    "    then\n"
    "\n"
    "    object@ word.prev object!      // step backwards thru words\n"
    "  next\n"
    "\n"
    "  // pipeout the infoset\n"
    "  StreamSet[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: lsten :: lsten ;\n"
    "\n"
    ": lsten_cmdTags _cmdTags tagCopy: localLiteOp_tags\n"
    "  tags{\n"
    "    <cmdDesc>     = \"--desc for op--\"\n"
    "    <streamDef>   = __listContents\n"
    "    <params>      = 0\n"
    "    <seedReq>     = \"lsten_req\"\n"
    "  }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

