    "    sSenLine \";\" str.same if\n"
    "      \" ;\" to sSenLine\n"
    "    then\n"
    "\n"
    "    \"    \\\"\"  pCppFile file.writeLine\n"
    "    sSenLine  pCppFile file.writeLine\n"
    "    \"\\\\n\\\"\"   pCppFile file.writeLine\n"
    "    \"\\n\"      pCppFile file.writeLine\n"
    "\n"
    "  repeat\n"
    "\n"
    "  \"    \\\"\\\\n\\\"\\n\"\n"
    "  pCppFile file.writeLine\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "//  sFileNm \"  \\\" CONSTANT %v \\\"_Stz\\n\" str.format\n"
    "//  pCppFile file.writeLine\n"
    "  \"    \\\"\\\"_Stz\\n\" str.format\n"
    "  pCppFile file.writeLine\n"
    "\n"
    "  \"  ;\\n\"\n"
    "  pCppFile file.writeLine\n"
    "\n"
    "//  \"\\n\"\n"
    "//  pCppFile file.writeLine\n"
    "//  i_File \"  vCompileMungedColon((i8)%v);\\n\" str.format\n"
    "//  pCppFile file.writeLine\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  \"\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"  szSubScriptDef =\"\n"
    "  pCppFile file.writeLine\n"
    "\n"
    "  sFileNm i_File \" \\\" %v CONSTANT %v \\\"_Stz;\\n\" str.format\n"
    "  pCppFile file.writeLine\n"
    "\n"
    "  \"  vCompileMungedColon(szSubScriptDef);\\n\" str.format\n"
    "  pCppFile file.writeLine\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* produce a c++ statement for the sen file                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_ProduceCppStatement params| pSenFile pCppFile i_File |\n"
    "\n"
    "  i_File pCppFile pSenFile munge_WriteDivider\n"
    "\n"
    "  i_File pCppFile pSenFile munge_WriteSenText_v2\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* munge one .sen file                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_ProcessSenFile params| sSenFileNm pCppFile i_File |\n"
    "\n"
    "  sSenFileNm file::sizeNm locals| nBytes |\n"
    "  nBytes sSenFileNm i_File \"[%v] %v %v bytes\" .printf\n"
    "\n"
    "  file::new locals| pSenFile |\n"
    "\n"
    "  sSenFileNm OPEN_READ pSenFile file.open assert\n"
    "\n"
    "  i_File pCppFile pSenFile munge_ProduceCppStatement\n"
    "\n"
    "  pSenFile file.close\n"
    "  pSenFile file.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* munge all .sen files in the sen dir                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_ProcessDir params| pSenDir pCppFile |\n"
    "\n"
    " 0 locals| i_File |\n"
    "\n"
    "  // read thru directory\n"
    "  begin pSenDir dir.read while\n"
    "\n"
    "    // ignore entries which aren't regular files\n"
    "    pSenDir dir.entryType DE_REG == not continue\n"
    "\n"
    "    // ignore entries which aren't .sen files\n"
    "    4 pSenDir dir.entryName str.right \".sen\" str.same not continue\n"
    "\n"
    "    // convert to C++\n"
    "    i_File pCppFile pSenDir dir.entryName munge_ProcessSenFile\n"
    "\n"
    "    i_File 1 + to i_File\n"
    "  repeat\n"
    "\n"
    "  i_File\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* write the .cpp header portion of the file                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_WriteCppHeader params| pCppFile |\n"
    "\n"
    "  \"/*============================================================================*/\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"/* MungedSen.cpp - munged sen files                                           */\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"/*============================================================================*/\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"#include \\\"BASE.h\\\"\\n\"\n"
    "  pCppFile file.writeLine\n"
    "\n"
    "  \"\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"Stz* gszaMungedText[1024];\\n\"\n"
    "  pCppFile file.writeLine\n"
    "\n"
    "  \"\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"void Task::vAddMunged(Task* )\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"{\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"  Stz* szSubScriptDef;\\n\"\n"
    "  pCppFile file.writeLine\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* write the .cpp footer portion of the file                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_WriteCppFooter params| pCppFile |\n"
    "\n"
    "  \"}\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"\\n\"\n"
    "  pCppFile file.writeLine\n"
    "\n"
    "  \"/*============================================================================*/\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"/* end                                                                        */\\n\"\n"
    "  pCppFile file.writeLine\n"
    "  \"/*============================================================================*/\\n\"\n"
    "  pCppFile file.writeLine\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* munge all .sen files                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge \\prompt\n"
    "\n"
    "  dir::new  locals| pSenDir |\n"
    "  file::new locals| pCppFile |\n"
    "\n"
    "  \"munging\" .\n"
    "\n"
    "  // save original dir and change to ../sen\n"
    "  dir::getCurrent locals| sOrigDir |\n"
    "  sOrigDir \"Original working directory: %v\" .printf\n"
    "\n"
    "  \"../sen\" dir::changeCurrent\n"
    "  dir::getCurrent \"Working directory now: %v\" .printf\n"
    "\n"
    "  // open sen directory\n"
    "  \".\" pSenDir dir.open assert\n"
    "\n"
    "  // open cpp file\n"
    "  \"../munge/Task_AddMunged.cpp\" OPEN_WRITE pCppFile file.open assert\n"
    "\n"
    "  pCppFile munge_WriteCppHeader\n"
    "\n"
    "  // munge the command dir\n"
    "  pCppFile pSenDir munge_ProcessDir locals| nSenProcessed |\n"
    "\n"
    "  pCppFile munge_WriteCppFooter\n"
    "\n"
    "  // close and delete file accessor\n"
    "  pCppFile file.close\n"
    "  pCppFile file.delete\n"
    "\n"
    "  pSenDir dir.close\n"
    "  pSenDir dir.delete\n"
    "\n"
    "  // change back to original dir\n"
    "  sOrigDir dir::changeCurrent\n"
    "  dir::getCurrent \"Working directory back to: %v\" .printf\n"
    "\n"
    "  nSenProcessed \"munged %v .sen files\" .printf\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 60 CONSTANT se_munge.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [61] job_PipelineLocal.sen

  gszaMungedText[61] =
    "\" munged job_PipelineLocal.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_PipelineLocal.sen -- Job Local Pipeline                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" job_PipelineLocal.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* terminate this pipeline                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pipelineLocal::termination ( -- )\n"
    "\n"
    "  DdlLock[].testDrop\n"
    "\n"
    "  JobRef[].none\n"
    "\n"
    "  Task[].grabLock TR_DELETE_THIS_TASK Task[].transition!\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_Pipeline request on origin                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pipelineLocal_req ( -- )\n"
    "\n"
    "  job::assertCorrectness\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // compile the pipeline command\n"
    "  \n"
    "  <cmd> Dynamo::compileStmt dup\n"
    "  EC_NONE == if\n"
    "    // clean compile\n"
    "    \n"
    "  else\n"
    "    //\"got error\" .\n"
    "    Job[].error!\n"
    "    \n"
    "    DdlLock[].testDrop\n"
    "\n"
    "    PipelineSpec[].delete\n"
    "        \n"
    "    // cross check\n"
    "    PipelineSpec[] not assert\n"
    "\n"
    "    JS_SIGNALLED Job[].state!\n"
    "      \n"
    "    Task[].grabLock\n"
    "    Session[].signal\n"
    "    Task[].dropLock\n"
    "    \n"
    "    pipelineLocal::termination\n"
    "    \n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // begin the pipeline job (spawning jobs for ops etc)\n"
    "  \n"
    "  PipelineSpec[] assert\n"
    "\n"
    "  Pipeline[].create\n"
    "  Pipeline[].spawnOpTasks\n"
    "\n"
    "  // run <pre_execute>\n"
    "\n"
    "  \"<pre_execute>\"\n"
    "  job::tagSet@ tagSet.hasName if\n"
    "    \"<pre_execute>\"\n"
    "    job::tagSet@ tagSet.getStr locals| sPreExe |\n"
    "    sPreExe find\n"
    "    dup not if\n"
    "      sPreExe \"Unable to find pre execute word: %v\" .printf\n"
    "      process::quit\n"
    "    then\n"
    "      execute\n"
    "  else\n"
    "    args.verbose if\n"
    "      <pipelineNm> \"No pre execute word for pipeline: %v\" .printf\n"
    "    then\n"
    "  then\n"
    "\n"
    "  // add job to the local job list\n"
    "  Job[] job.jobList@ JL_DEMON == not if\n"
    "    Job[].addLocal\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab the task lock\n"
    "  Task[].grabLock\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // execute the pipeline job (send startmarker to start)\n"
    "  //<pipelineNm> \"%v execute\" .printf\n"
    "  Pipeline::enqueueStart if\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // wait for operators to finish\n"
    "    //<pipelineNm> grid::thisNodeName@ \"(%v) %v waiting on Task[].wait\" .printf\n"
    "    Task[].wait\n"
    "    //<pipelineNm> grid::thisNodeName@ \"(%v) %v running\" .printf\n"
    "  else\n"
    "    //<pipelineNm> grid::thisNodeName@ \"(%v) nothing to do\" .printf\n"
    "    Task[].dropLock\n"
    "  then\n"
    "\n"
    "  // remove job from the local job list\n"
    "  Job[] job.jobList@ JL_DEMON == not if\n"
    "    Job[].removeLocal\n"
    "  then\n"
    "\n"
    "  //<pipelineNm> grid::thisNodeName@ \"(%v) ALL DONE!!!\" .printf\n"
    "  \n"
    "  Job[].addRetired\n"
    "  [? WITH_JOB_REAPING ?if \"reaping\" . ?else Job[].removeRetired ?]\n"
    "      \n"
    "  JS_SIGNALLED Job[].state!\n"
    "      \n"
    "  Task[].grabLock\n"
    "  Session[].signal\n"
    "  Task[].dropLock\n"
    " \n"
    "  pipelineLocal::termination\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "cmdSyntax: pipelineLocal :: pipelineLocal <pipelineNm> etc ;\n"
    "\n"
    ": pipelineLocal_cmdTags _cmdTags tagCopy: localJob_tags\n"
    "  tags{\n"
    "    <cmdDesc>  = \"--desc for job--\"\n"
    "\n"
    "    <jobKind>  = JK_LOCAL\n"
    "    //<ddlLock>  = DL_GRAB_READ\n"
    "    \n"
    "    <seedReq>   = \"pipelineLocal_req\"\n"
    "  }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 61 CONSTANT job_PipelineLocal.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [62] OP_syntaxIndex.sen

  gszaMungedText[62] =
    "\" munged OP_syntaxIndex.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_syntaxIndex.sen -- Operator syntax index                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_syntaxIndex.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if <tableNm> . <indexNm> is a creatable index                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": syntaxIndex::checkCreate ( sTableNm --  true | errorCode false )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // check in tables folder: ../schemas/public/tables\n"
    "  check::folderIsTables not if false exit then\n"
    "\n"
    "  // check there is a sub-folder by the name of the table\n"
    "  //   ../schemas/public/tables/t\n"
    "  sTableNm check::folderHasNamedTable not if false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if max indexes already on table\n"
    "\n"
    "  // push into t: ../schemas/public/tables/t \\folder\n"
    "  sTableNm Path[].pushNamedTableFolder\n"
    "\n"
    "  // check max indexes\n"
    "  sTableNm find execute to Table[]\n"
    "  Table[] table.indexCount C_MAX_INDEXES == if\n"
    "    EC_MAX_INDEXES\n"
    "    Path[].popNamedTableFolder\n"
    "    Folder[].isTables assert\n"
    "    false exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check name doesn't already exist\n"
    "\n"
    "  // push into indexes: ../schemas/public/tables/t/indexes\n"
    "  Path[].pushIndexesFolder\n"
    "  Folder[].isIndexes assert\n"
    "\n"
    "  // error if given name already exists\n"
    "  <indexNm> check::nameIsUnknownIndex not if\n"
    "    Path[].popIndexesFolder\n"
    "    Path[].popNamedTableFolder\n"
    "    Folder[].isTables assert\n"
    "    false exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop upto tables: ../schemas/public/tables\n"
    "\n"
    "  Path[].popIndexesFolder\n"
    "  Path[].popNamedTableFolder\n"
    "  Folder[].isTables assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_M_DATAPULSE ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": syntaxIndex_DataMarker\n"
    "\n"
    "  0 0 0 locals| sTableNm sSmt errorCode |\n"
    "\n"
    "  //job::tagSet@ tagSet.asStr .\n"
    "  Pipein[].pipeout\n"
    "\n"
    "  // is it a unique index ?\n"
    "  \"<unique>\" job::tagSet@ tagSet.hasName if\n"
    "    <etc> <indexNm> \"create unique index %v %v ;\" str.format to sSmt\n"
    "  else\n"
    "    <etc> <indexNm> \"create index %v %v ;\" str.format to sSmt\n"
    "  then\n"
    "\n"
    "  sSmt .\n"
    "\n"
    "  // parse the smt and get the table name\n"
    "  sSmt Job[] indexDef::parseTableName to sTableNm\n"
    "  Job[].error@ to errorCode\n"
    "  sTableNm \"\" str.equal if\n"
    "    Job[].error@ to errorCode\n"
    "    errorCode op__execErr\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // check ok to create index\n"
    "  sTableNm syntaxIndex::checkCreate not if ( errorCode )\n"
    "    to errorCode\n"
    "    errorCode op__execErr\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  sSmt Table[] Job[] indexDef::parse to IndexDef[]\n"
    "\n"
    "  IndexDef[].isNull if\n"
    "    Job[].error@ to errorCode\n"
    "    errorCode op__execErr\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // should be in tables\n"
    "  Folder[].isTables assert\n"
    "\n"
    "  IndexDef[].pipeout\n"
    "\n"
    "  // should be in tables\n"
    "  Folder[].isTables assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for syntaxTable req                        (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": syntaxIndex_req \\operator\n"
    "\n"
    "  _lu_initialise_\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: syntaxIndex_DataMarker ZK_M_DATAPULSE op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  _lu_finalise_\n"
    "  \n"
    "  op__retires\n"
    "  \n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: syntaxIndex :: syntaxIndex <indexNm> <etc> ;\n"
    "\n"
    ": syntaxIndex_cmdTags _cmdTags tagCopy: op_tags\n"
    "  tags{\n"
    "    <cmdDesc>   = \"--description of operator--\" }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 62 CONSTANT OP_syntaxIndex.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

