  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [81] OP_changeFolder.sen

  gszaMungedText[81] =
    "\" munged OP_changeFolder.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_changeFolder.sen -- Operator change flolder                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_changeFolder.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": cf_action\n"
    "\n"
    "  0 0 locals| pCurrentFolder sFolderNm |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // get the folderNm from the the tag\n"
    "  <folderNm> to sFolderNm\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // test for a \"..\" which will go up one folder\n"
    "\n"
    "  // pop up one folder, but not into tenants\n"
    "  sFolderNm \"..\" str.same if\n"
    "    Folder[] dic.name@ \"tenants\" str.same not if Path[].popFolder then\n"
    "    setPath\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // test for a \"~\" will pop folder path till it reaches /tenants\n"
    "\n"
    "  // pop up to tenants\n"
    "  sFolderNm \"~\" str.same if\n"
    "    begin Folder[] dic.name@ \"tenants\" str.same not while Path[].popFolder repeat\n"
    "    setPath\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // set default catalogs\n"
    "  sFolderNm \"~catalogs\" str.same if\n"
    "    setCatalogs\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // set default schemas\n"
    "  sFolderNm \"~schemas\" str.same if\n"
    "    setSchemas\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // set default tables\n"
    "  sFolderNm \"~tables\" str.same if\n"
    "    setTables\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // test for a \"tenants\" will clear folder path and set to /tenants\n"
    "\n"
    "  // clear dic path and push tenants\n"
    "  sFolderNm \"tenants\" str.same if\n"
    "    Path[].popAllFolders\n"
    "    attachmap::tenants@ execute Path[].pushFolder\n"
    "    setPath\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // otherwise we expect a name of a sub-folder to which we push path to\n"
    "  //  push sub-folder\n"
    "\n"
    "  sFolderNm Folder[].findSymbol to pCurrentFolder\n"
    "\n"
    "  pCurrentFolder word.checkIsAFolder not if\n"
    "    op__execErr\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  pCurrentFolder execute Path[].pushFolder\n"
    "  setPath\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: cf :: cf <folderNm> ;\n"
    "\n"
    ": cf_cmdTags _cmdTags tagCopy: localLiteOp_tags\n"
    "  tags{\n"
    "    <cmdDesc>     = \"--desc for op--\"\n"
    "    <params>      = 1\n"
    "    \n"
    "    <seedReq>   = \"cf_req\"\n"
    "  }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 81 CONSTANT OP_changeFolder.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

