    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate g definitions                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gCol ( eColumn -- sColType )\n"
    "\n"
    "  params| eColumn |\n"
    "\n"
    "  eColumn case\n"
    "\n"
    "    CT_BOOLEAN   of \"boolean\"   endof\n"
    "    CT_CHAR      of \"char\"      endof\n"
    "    CT_DATE      of \"date\"      endof\n"
    "    CT_DECIMAL   of \"decimal\"   endof\n"
    "    CT_FLOAT     of \"float\"     endof\n"
    "    CT_INTEGER   of \"integer\"   endof\n"
    "    CT_INTERVAL_DT  of \"interval\"  endof\n"
    "    CT_TIME      of \"time\"      endof\n"
    "    CT_TIMESTAMP of \"timestamp\" endof\n"
    "    CT_VARCHAR   of \"varchar\"   endof\n"
    "\n"
    "  endcase\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate g definitions                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gRecurse ( iDepth -- )\n"
    "\n"
    "  params| iDepth |\n"
    "\n"
    "  iDepth .\n"
    "\n"
    "  iDepth if\n"
    "    iDepth 1 - to iDepth\n"
    "    iDepth gRecurse\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate g definitions                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gGen\n"
    "\n"
    "  9 gRecurse\n"
    "\n"
    "  CT_ENUMS CT_BOOLEAN\n"
    "  do\n"
    "    I .\n"
    "    I gCol .\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

