    "  indexStream[].open\n"
    "\n"
    "  // position in the index\n"
    "  iPhrase  // phrase\n"
    "  lowerKey // lower\n"
    "  upperKey // upper\n"
    "  PathIdentifier[] indexStream[].seek\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin the delete                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": beginDelete ( iPhrase -- )\n"
    "\n"
    "  params| iPhrase |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the fetch technique\n"
    "  iPhrase PathIdentifier[].fetchTech@\n"
    "\n"
    "  case\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an exact select using index\n"
    "    AT_EXACT of\n"
    "      \"*exact*\" .verbose\n"
    "\n"
    "      iPhrase                  // phrase\n"
    "      iPhrase PathIdentifier[].key@   // lower key\n"
    "      iPhrase PathIdentifier[].key@   // upper key\n"
    "      positionBeginDelete\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // lower bound select using index\n"
    "    AT_LOWER of\n"
    "      \"*lower*\" .verbose\n"
    "\n"
    "      iPhrase                     // phrase\n"
    "      iPhrase PathIdentifier[].lowKey@   // lower key\n"
    "      \"\"                          // upper key\n"
    "      positionBeginDelete\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an upper bound select using index\n"
    "    AT_UPPER of\n"
    "      \"*upper*\" .verbose\n"
    "\n"
    "      iPhrase                     // phrase\n"
    "      \"\"                          // lower key\n"
    "      iPhrase PathIdentifier[].upperKey@ // upper key\n"
    "      positionBeginDelete\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // a range select using index\n"
    "    AT_RANGE of\n"
    "      \"*range\" .verbose\n"
    "\n"
    "      iPhrase                     // phrase\n"
    "      iPhrase PathIdentifier[].lowKey@   // lower key\n"
    "      iPhrase PathIdentifier[].upperKey@ // upper key\n"
    "      positionBeginDelete\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // full scan (no index)\n"
    "    AT_SCAN of\n"
    "      \"*scan*\" .verbose\n"
    "      // now get excat key rows from index\n"
    "      TablePtn[].grabRead_yieldLoop\n"
    "      TablePtn[] ptnStream::new to ptnStream[]\n"
    "\n"
    "      // open ptn stream for the tablePtn\n"
    "      ptnStream[] ptnStream.open assert\n"
    "    endof\n"
    "\n"
    "  endcase\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate plan for the fetch                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": generatePlan ( -- )\n"
    "\n"
    "  0 locals| sPredicate |\n"
    "\n"
    "  //sWhere \"generatePlan\" \"%v %v\" str.format .\n"
    "\n"
    "  ( cdt_0 ) PathIdentifier[].new\n"
    "  ( cdt_1 ) Table[] PathIdentifier[].table!\n"
    "\n"
    "  ( cdt_2 ) <predicate> PathIdentifier[].parseWhere  //\"parseWheres\" .\n"
    "\n"
    "  ( cdt_3 ) PathIdentifier[].genPaths           //\"genPaths\" .\n"
    "  ( cdt_4 ) PathIdentifier[].scorePaths         //\"scorePaths\" .\n"
    "  //( cdt_5 ) PathIdentifier[].showPaths\n"
    "\n"
    "  ( cdt_6 ) PathIdentifier[].matchPaths         //\"matchPaths\" .\n"
    "  //( cdt_6 ) PathIdentifier[].showPaths\n"
    "\n"
    "  ( cdt_7 ) PathIdentifier[].choosePaths        //\"choosePaths\" .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_M_CLEANING ...                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": delete_Cleaning \\handler\n"
    "\n"
    "  //\"ZK_M_CLEANING_handler\" .verbose\n"
    "\n"
    "  ZK_M_CLEANING_handler\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for delete_rows ...                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": delete_rows \\handler\n"
    "\n"
    "  \"Handler:- delete_rows\" .verbose\n"
    "\n"
    "  0 locals| bMoreToDelete |\n"
    "\n"
    "  // get the fetchTechnique\n"
    "  Counter1[] PathIdentifier[].fetchTech@\n"
    "  case\n"
    "    AT_SCAN of\n"
    "     0 assert\n"
    "    endof\n"
    "\n"
    "    indexStream[].deleteNext to bMoreToDelete\n"
    "\n"
    "  endcase\n"
    "\n"
    "  // no more data for counter1[] phrase ?\n"
    "  bMoreToDelete not if\n"
    "\n"
    "    // any more phrases ?\n"
    "    Counter1[] 1 + to Counter1[]\n"
    "    Counter1[] Counter0[] >= if\n"
    "      // all done\n"
    "      // close and delete partition stream\n"
    "      ptnStream[].isNull not if\n"
    "        ptnStream[] ptnStream.close\n"
    "        ptnStream[] ptnStream.delete\n"
    "        nullptr to ptnStream[]\n"
    "      then\n"
    "\n"
    "      // close and delete index stream\n"
    "      indexStream[].isNull not if\n"
    "        indexStream[].close\n"
    "        indexStream[].delete\n"
    "        nullptr to indexStream[]\n"
    "      then\n"
    "\n"
    "      TablePtn[].dropRead\n"
    "\n"
    "      // delete the path identifier\n"
    "      PathIdentifier[].delete\n"
    "      nullptr to PathIdentifier[]\n"
    "\n"
    "      // pipeout an eosMarker\n"
    "      Marker[].newEosMarker\n"
    "      Marker[].pipeOut\n"
    "    else\n"
    "      // position and fetch first buffer for next phrase\n"
    "      Counter1[] beginDelete\n"
    "    then\n"
    "\n"
    "  else\n"
    "\n"
    "    // call this handler again to process next buffer\n"
    "    true LogicUnit[].callAgain!\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_M_DATAPULSE ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": delete_DataMarker \\handler\n"
    "\n"
    "  0 locals| iPhrases |\n"
    "\n"
    "  //\"Operand:- ZK_M_DATAPULSE\" .verbose\n"
    "  PipeIn[].pipeOut\n"
    "\n"
    "  // new a stream def\n"
    "  Table[] StreamDefOut[].newFromTable\n"
    "  StreamDefOut[].pipeOut\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get no of phrases\n"
    "  PathIdentifier[].phrases@ to Counter0[]\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // assert we have at least one phrase\n"
    "  Counter0[] 1 >= assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set counter1[] to 0\n"
    "  0 to Counter1[]\n"
    "\n"
    "  // position and begin delete for the first phrase\n"
    "  Counter1[] beginDelete\n"
    "\n"
    "  // force op loop to call fetch_CrwBuffer to start processing buffers\n"
    "  \"delete_rows\" word::find LogicUnit[].handler!\n"
    "  true LogicUnit[].callAgain!\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_M_START ...                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": delete_StartMarker \\handler\n"
    "\n"
    "  //\"Operand:- ZK_M_START\" .verbose\n"
    "\n"
    "  0 locals| iPhrases |\n"
    "\n"
    "  PipeIn[].pipeOut\n"
    "\n"
    "  <tableNm> op__table if\n"
    "    Table[].tablePtn@ to TablePtn[]\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // generate the plan for the fetch\n"
    "  generatePlan\n"
    "\n"
    "  //PathIdentifier[].showPaths\n"
    "\n"
    "  // assert we have a plan\n"
    "  PathIdentifier[].isNull not assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* delete request                                     (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": delete_req \\operator\n"
    "\n"
    "  _lu_initialise_\n"
    "  //<tableNm> <predicate> \"PARAMETERS %v %v\" str.format .\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: delete_Cleaning      ZK_M_CLEANING      op[].handler!\n"
    "  //find: delete_CrwBuffer   ZK_D_CRWBUFFER     op[].handler!\n"
    "  find: delete_DataMarker    ZK_M_DATAPULSE     op[].handler!\n"
    "  find: delete_StartMarker   ZK_M_START         op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  _lu_finalise_\n"
    "  \n"
    "  op__retires\n"
    "  \n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: delete :: delete <tableNm> <predicate> ;\n"
    "\n"
    ": delete_cmdTags _cmdTags tagCopy: op_tags\n"
    "  tags{ <cmdDesc> = \"--desc for op--\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 126 CONSTANT OP_delete.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

