  // munge of [133] grid_grid.sen

  gszaMungedText[133] =
    "\" munged grid_grid.sen \" .verbose \n"
    " /*============================================================================*/\n"
    "/* grid.sen -- grid routines                                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" grid_grid.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* form the shell command for spawning and starting a node etc                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .formShellCommand params| sNodeList sNodeName bAdd |\n"
    "\n"
    "  //  \"nohup \"\n"
    "  \"\"\n"
    "\n"
    "  executable::isDebug if\n"
    "    //\"../OS\\\\ X/Build/Products/Debug/SE\" str.cat\n"
    "    \"../bin/rapidsse\" str.cat\n"
    "  else\n"
    "    //\"../OS\\\\ X/Build/Products/Release/SE\" str.cat\n"
    "    \"../bin/rapidsse\" str.cat\n"
    "  then\n"
    "\n"
    "  \" --start\" str.cat\n"
    "  bAdd if\n"
    "    \" --addNode\" str.cat\n"
    "  then\n"
    "\n"
    "  \" --name \"  str.cat sNodeName str.cat\n"
    "\n"
    "  sNodeList str.cat\n"
    "\n"
    "  \" --size \"              str.cat args.regionSize        >str   str.cat\n"
    "  \" --regionPrefix \"      str.cat args.regionPrefix             str.cat\n"
    "  \" --partitionsPerNode \" str.cat args.partitionsPerNode >str   str.cat\n"
    "  \" --maxReadyLP \"        str.cat args.maxReadyLP        >str   str.cat\n"
    "\n"
    "  user::name \"alka\" str.same if\n"
    "     \" --commands /Users/alka/rapidsse/commands\" str.cat\n"
    "  then\n"
    "\n"
    "  // user::name \"craig\" str.same if\n"
    "  //       \" --commands /Users/craig/rapidsse/commands\" str.cat\n"
    "  // then\n"
    "\n"
    "  user::name \"ray\" str.same if\n"
    "    \" --commands /Users/ray/rapidsse/commands\"  str.cat\n"
    "  then\n"
    "\n"
    "  user::name \"myvanquoc\" str.same if\n"
    "     \" --commands /Users/myvanquoc/dev/src/SE/rapidsse/commands\" str.cat\n"
    "  then\n"
    "\n"
    "\n"
    "\n"
    "  args.tracepoint  if \" --tracepoint\"   str.cat then\n"
    "  args.verbose     if \" --verbose\"      str.cat then\n"
    "  args.dontFree    if \" --dontFree\"     str.cat then\n"
    "  args.freeCB      if \" --freeSpecific\" str.cat then\n"
    "  args.metadata    if \" --metadata\"     str.cat then\n"
    "  args.munged      if \" --munged\"       str.cat then\n"
    "  args.heartbeat   if \" --heartbeat BROADCAST 8888\" str.cat then\n"
    "\n"
    "  \" &\" str.cat locals| sShellCmd |\n"
    " \n"
    "  sShellCmd\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* form the node list: {--node name ip port}*                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .formNodeList ( -- sNodeList )\n"
    "\n"
    "  0 locals| pNode |\n"
    "\n"
    "  C_ALL node_I[].new\n"
    "\n"
    "  \"\" // initial empty string\n"
    "\n"
    "  begin\n"
    "\n"
    "    node_I[].node to pNode\n"
    "\n"
    "    pNode node.port\n"
    "    pNode node.IP\n"
    "    pNode node.name\n"
    "    \" --node %v %v %v\" str.format\n"
    "    str.cat\n"
    "\n"
    "    node_I[].next\n"
    "    node_i[].more while\n"
    "  repeat\n"
    "\n"
    "  node_I[].delete\n"
    "\n"
    "  CN_STZVAL assert::class\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn a specific node                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .spawnNamedNode ( bAdd sNodeName sNodeList -- )\n"
    "\n"
    "  params| sNodeList |\n"
    "  params| sNodeName |\n"
    "  params| bAdd      |\n"
    "\n"
    "  0 locals| sShellCommand |\n"
    "\n"
    "  // form the shell command\n"
    "  bAdd sNodeName sNodeList .formShellCommand to sShellCommand\n"
    "\n"
    "  // print the shell command\n"
    "  sShellCommand .\n"
    "\n"
    "  // execute the shell command\n"
    "  sShellCommand shell::execute\n"
    "\n"
    "  // check result\n"
    "  not assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn all other nodes for a grid on this machine                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::spawnOtherNodes ( -- )\n"
    "\n"
    "  // test for single node grid\n"
    "  sysargs::definedNodes 1 == if exit then\n"
    "\n"
    "  0 locals| sNodeList |\n"
    "  0 locals| sShellCommand |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // form the node list\n"
    "\n"
    "  .formNodeList to sNodeList\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // spawn all other nodes\n"
    "\n"
    "\n"
    "  0 locals| pNode |\n"
    "\n"
    "  0 node_I[].new\n"
    "\n"
    "  begin\n"
    "\n"
    "    node_I[].node to pNode\n"
    "\n"
    "    pNode node.isThisNode not if\n"
    "\n"
    "      false  pNode node.name  sNodeList  .spawnNamedNode\n"
    "\n"
    "    then\n"
    "\n"
    "    node_I[].next\n"
    "    node_i[].more while\n"
    "  repeat\n"
    "\n"
    "  node_I[].delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn named node being added to a grid on this machine                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::spawnAddingNode ( sNodeNm -- )\n"
    "\n"
    "  params| sNodeNm   |\n"
    "\n"
    "  0 locals| sNodeList |\n"
    "\n"
    "  // form the node list\n"
    "  .formNodeList to sNodeList\n"
    "\n"
    "  // spawn/add node sNodeNm\n"
    "  true   sNodeNm   sNodeList  .spawnNamedNode\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set start node                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::setStartNode ( -- )\n"
    "\n"
    "  // set this node as the grid start node\n"
    "  // grid::thisNode@ grid::StartNode!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forget named node (run by all participants)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::forgetNode ( \"<NodeNm>\" )\n"
    "\n"
    "  params| sNodeNm |\n"
    "\n"
    "  sNodeNm grid::findNodeByName node.forget\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 133 CONSTANT grid_grid.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

