  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [143] OP_rdCsvCyclic.sen

  gszaMungedText[143] =
    "\" munged OP_rdCsvCyclic.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_rdCsvCyclic.sen -- read csv cyclically                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_rdCsvCyclic.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* catFile csvBuffer                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rdCsvCyclic_catCsv\n"
    "\n"
    "  csvBuffer::new to CsvBuffer[]\n"
    "\n"
    "  CsvBuffer[] file0[] file.readChunk if\n"
    "    file0[] file.tell \"read a csv chunk (tell %v)\" .printf\n"
    "    CsvBuffer[].pipeOut\n"
    "\n"
    "    \"SLEEPING for 1 sec\" .\n"
    "    1 task::sleepSsec\n"
    "\n"
    "    true\n"
    "  else\n"
    "    false\n"
    "  then\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_M_DATAPULSE ...                                                   INIT */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rdCsvCyclic_DataMarker \\handler\n"
    "\n"
    "  PipeIn[].pipeOut\n"
    "\n"
    "  file::new to file0[]\n"
    "\n"
    "  <fileNm> OPEN_READ file0[] file.open if\n"
    "    file0[] file.size <fileNm> \"File %v opened (%v bytes)\" .printf\n"
    "\n"
    "    file0[] file.seekRndCsv\n"
    "\n"
    "    <nTimes> >int 0 do\n"
    "\n"
    "      Task[].yield \n"
    "\n"
    "      begin\n"
    "        // check for low memory\n"
    "        attachMap::isLowMemory if\n"
    "          EC_LOW_MEMORY op__execErr\n"
    "          file0[].get file.close\n"
    "          <fileNm> \"File %v closed\" .printf\n"
    "          true\n"
    "          exit\n"
    "        then\n"
    "\n"
    "        rdCsvCyclic_catCsv\n"
    "\n"
    "      while repeat\n"
    "\n"
    "      0 file0[] file.seek\n"
    "\n"
    "      \"SLEEPING for 1 secs\" .\n"
    "      1 task::sleepSsec\n"
    "    loop\n"
    "\n"
    "    file0[].get file.close\n"
    "    <fileNm> \"File %v closed\" .printf\n"
    "\n"
    "    Marker[].newEosMarker\n"
    "    Marker[].pipeOut\n"
    "\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* rdCsvCyclic request                                                  SPAWN */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rdCsvCyclic_req \\operator\n"
    "\n"
    "  _lu_initialise_\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: rdCsvCyclic_DataMarker ZK_M_DATAPULSE op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  _lu_finalise_\n"
    "  \n"
    "  op__retires\n"
    "  \n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: rdCsvCyclic :: rdCsvCyclic <fileNm> <nTimes> ;\n"
    "\n"
    ": rdCsvCyclic_cmdTags _cmdTags tagCopy: op_tags tags{ <cmdDesc> = \"--desc for op--\" } ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

