  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [149] db_schema.sen

  gszaMungedText[149] =
    "\" munged db_schema.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_schema.sen -- schema related words                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" db_schema.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* the schema category                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\schema \\\\category ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the schema folder                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Path[].popSchemaFolder\n"
    "\n"
    "  Path[].popFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if current folder is ../tables                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Folder[].isSchemas\n"
    "\n"
    "  Folder[] dic.name@ \"schemas\" str.same\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check current folder is ../schemas                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Folder[].checkIsSchemas\n"
    "\n"
    "  Folder[].isSchemas if true exit then\n"
    "  \n"
    "  EC_NOT_IN_SCHEMAS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is a schemas                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsSchema ( word )\n"
    "\n"
    "  Folder[].findSymbol if true exit then\n"
    "  EC_NOT_A_SCHEMA false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is a schema                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Path[].checkIsSchema ( word )\n"
    "\n"
    "  dup word.category@ find: \\folder equal not if EC_NOT_A_FOLDER false exit then\n"
    "  dup execute dic.kind@ find: \\schema equal if true exit then\n"
    "  EC_NOT_A_SCHEMA false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable schema folder                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveSchema ( \"<schemaNm>\" --  true | errorCode false )\n"
    "\n"
    "  params| sSchemaNm |\n"
    "\n"
    "  Folder[].checkIsSchemas not if false exit then\n"
    "  //sSchemaNm word::isKnown not if EC_NO_SUCH_SCHEMA false exit then\n"
    "  sSchemaNm checkIsSchema  not if false exit then\n"
    "  //folder.isEmpty   not if false exit then\n"
    "  //folder.notUsed   not if false exit then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a schema folder                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :makeSchemaFolder params| sSchemaNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    sSchemaNm \"MAKING SCHEMA \" swap str.cat \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    " // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    " // make the schema\n"
    " sSchemaNm folder::makeFolder\n"
    "   find: \\schema swap execute dic.kind!\n"
    "\n"
    " // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    " // make tables folder\n"
    " sSchemaNm table::makeTablesFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a schemas folder under given named catalog                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :makeSchemasFolder ( \"<catalogNm>\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \"MAKING SCHEMAS FOR CATALOG \" swap str.cat \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \"schemas\"    ( dic \"schemas\" )\n"
    "  swap         ( \"schemas\" dic )\n"
    "  folder::makeSubFolder   ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the schema folder and push it onto task dictionary                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Path[].pushSchemaFolder ( \"<schemaName>\" -- )\n"
    "\n"
    "  find execute Path[].pushFolder\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a schema folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeSchema ( \"<schemaNm>\" --  )\n"
    "\n"
    "  params| sSchemaNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "  dup \"REMOVING SCHEMA \" swap str.cat \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // move to schema folder\n"
    "  sSchemaNm Path[].pushSchemaFolder assert\n"
    "\n"
    "  \"tables\" folder::remove\n"
    "\n"
    "  Path[].popSchemaFolder\n"
    "\n"
    "  sSchemaNm folder::remove\n"
    " ;\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 149 CONSTANT db_schema.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

