  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [182] se_tags.sen

  gszaMungedText[182] =
    "\" munged se_tags.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* se_tags.sen -- tags                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" se_tags.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add given tag to word's tag set  (with support for constant translation)   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tagSet.addTag params| pWordTagSet sTagValue sTagName |\n"
    "\n"
    "  sTagValue find     locals| pConstantWord |\n"
    "\n"
    "  // test for a (int) constant and translate value\n"
    "  pConstantWord if\n"
    "    pConstantWord word.category@ find: rootConstant equal if\n"
    "\n"
    "      // sEvalue \"  %v is a constant\" .printf\n"
    "      // add <name> = <constant>\n"
    "      sTagName pConstantWord execute pWordTagSet tagSet.insertInt\n"
    "      exit\n"
    "\n"
    "    then\n"
    "  then\n"
    "\n"
    "  // add <name> = <string>\n"
    "  sTagName sTagValue pWordTagSet tagSet.insertStr\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add/replace given tag to word's tag set (support for constant translation) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tagSet.addReplaceTag params| pWordTagSet sTagValue sTagName |\n"
    "\n"
    "  sTagValue find     locals| pConstantWord |\n"
    "\n"
    "  // test for a (int) constant and translate value\n"
    "  pConstantWord if\n"
    "    pConstantWord word.category@ find: rootConstant equal if\n"
    "\n"
    "      // sEvalue \"  %v is a constant\" .printf\n"
    "      // add/replace <name> = <constant>\n"
    "      sTagName pConstantWord execute pWordTagSet tagSet.replaceInt\n"
    "      exit\n"
    "\n"
    "    then\n"
    "  then\n"
    "\n"
    "  // add/replace <name> = <string>\n"
    "  sTagName sTagValue pWordTagSet tagSet.replaceStr\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* the job info compiler                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tags{ immediate\n"
    "  \n"
    "  0 locals| pTagSet |\n"
    "\n"
    "  // attach a new ename set to the word being created\n"
    "  //tagSet::new to pTagSet\n"
    "  //pTagSet senCompiler::current@ word.TagSet!\n"
    "  senCompiler::current@ word.EnsureTagSet\n"
    "  senCompiler::current@ word.TagSet@ to pTagSet\n"
    "  \n"
    "  // add tag set name\n"
    "  \n"
    "  \"<aTagSetNm>\" senCompiler::current@ word.name@ senCompiler::current@ word.TagSet@ tagSet.addReplaceTag\n"
    "  \n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // parse each input token till \"}\", build ename set representing the syntax\n"
    "\n"
    "  0 0 locals| sTagName sTagValue |\n"
    "\n"
    "  begin\n"
    "  \n"
    "    input::next\n"
    "    \n"
    "    dup \"}\" str.same not\n"
    "    \n"
    "  while\n"
    "  \n"
    "    // collect the tag name\n"
    "    to sTagName\n"
    "    \n"
    "    // skip the =\n"
    "    input::next discard\n"
    "    \n"
    "    // collect the tag value\n"
    "    input::next to sTagValue\n"
    "    \n"
    "    // add the decoded\n"
    "    sTagName sTagValue senCompiler::current@ word.TagSet@ tagSet.addReplaceTag\n"
    "  \n"
    "  repeat\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // discard the \"}\" from dstack\n"
    "  discard\n"
    "  \n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //senCompiler::current@ encode::push\n"
    "  \n"
    "  //POSTPONE word.tagSet@\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* copy ename set of input::next and copy into word being compiled             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tagCopy: immediate ( -- )\n"
    "\n"
    "  0 0 0 0 locals| pEnamSetDst pEnamSetSrc pDstTagWord pSrcTagWord |\n"
    "  \n"
    "  // get the ename set of the word being compiled\n"
    "  senCompiler::current@ to pDstTagWord\n"
    "  \n"
    "  pDstTagWord word.EnsureTagSet\n"
    "\n"
    "  pDstTagWord word.tagSet@ to pEnamSetDst\n"
    "  \n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  \n"
    "  // get the ename set to be copied\n"
    "  input::next find to pSrcTagWord\n"
    "  \n"
    "  pSrcTagWord not if\n"
    "  then\n"
    "    \n"
    "  pSrcTagWord word.tagSet@ to pEnamSetSrc\n"
    "  \n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    \n"
    "  // copy source ename set into destination\n"
    "  pEnamSetSrc pEnamSetDst tagSet.copy\n"
    " ;\n"
    "  \n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* are current input chars a json token ?                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": input::isEtc\n"
    "\n"
    "  input::chars \"etc\" str.same\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* are current input chars a json token ?                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": input::isJson\n"
    "\n"
    "  input::chars str.isJsonToken\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* are current input chars a meta token ?  <tag>                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": input::isTag\n"
    "\n"
    "  input::chars str.isMetaToken\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* are current input chars a close brace i.e. '}' ?                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": input::isCloseBrace\n"
    "\n"
    "  input::chars \"}\" str.same\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* are current input chars an exclamation i.e. '!' ?                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": input::isExclamation\n"
    "\n"
    "  input::chars \"!\" str.same\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 182 CONSTANT se_tags.sen "_Stz;
