    "/*----------------------------------------------------------------------------*/\n"
    "/* the catalog category                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\catalog \\\\category ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the catalog folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Path[].popCatalogFolder\n"
    "\n"
    "  Path[].popFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if current folder is ../catalogs                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Folder[].isCatalogs\n"
    "\n"
    "  Folder[] dic.name@ \"catalogs\" str.same\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check current folder is ../catalogs                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Folder[].checkIsCatalogs\n"
    "\n"
    "  Folder[].isCatalogs if true exit then\n"
    "  EC_NOT_IN_CATALOGS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is a catalog                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Path[].checkIsCatalog ( word )\n"
    "\n"
    "  dup word.category@ find: \\folder equal not if EC_NOT_A_FOLDER false exit then\n"
    "  dup execute dic.kind@ find: \\catalog equal if true exit then\n"
    "  EC_NOT_A_CATALOG false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is a catalog                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsCatalog ( word )\n"
    "\n"
    "  Folder[].findSymbol if true exit then\n"
    "  EC_NOT_A_CATALOG false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is not a catalog                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": name::isNotKnownCatalog ( word )\n"
    "\n"
    "  Folder[].findSymbol not if true exit then\n"
    "  EC_CATALOG_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable catalog folder                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveCatalog ( \"<catalogNm>\" --  true | errorCode false )\n"
    "\n"
    "  params| sCatalogNm |\n"
    "\n"
    "  Folder[].checkIsCatalogs not if false exit then\n"
    "  //sCatalogNm word::isKnown not if EC_NO_SUCH_CATALOG false exit then\n"
    "  sCatalogNm checkIsCatalog  not if false exit then\n"
    "  //folder.isEmpty   not if false exit then\n"
    "  //folder.notUsed   not if false exit then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a catalogs folder under given named tenant                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :makeCatalogsFolder ( <catalogNm> -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "  dup \"MAKING CATALOGS FOR TENANT \" swap str.cat \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \"catalogs\"   ( dic \"catalogs\" )\n"
    "  swap         ( \"catalogs\" dic )\n"
    "  folder::makeSubFolder   ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a named catalog folder (run by participant)                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :makeCatalogFolder params| sCatalogNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "   sCatalogNm \"MAKING CATALOG \" swap str.cat \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // make the catalog\n"
    "  sCatalogNm folder::makeFolder\n"
    "    find: \\catalog swap execute dic.kind!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // make catalogs folder\n"
    "  sCatalogNm :makeSchemasFolder ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the catalog folder and push it onto task dictionary                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Path[].pushCatalogFolder ( \"<catalogName>\" -- )\n"
    "\n"
    "  find execute Path[].pushFolder\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a catalog folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeCatalog ( \"<catalogNm>\" --  )\n"
    "\n"
    "  params| sCatalogNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \"REMOVING CATALOG \" swap str.cat \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // move to catalog folder\n"
    "  sCatalogNm Path[].pushCatalogFolder assert\n"
    "\n"
    "  \"schemas\" folder::remove\n"
    "\n"
    "  Path[].popCatalogFolder\n"
    "\n"
    "  sCatalogNm folder::remove\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

