  // munge of [220] db_tenant.sen

  gszaMungedText[220] =
    "\" munged db_tenant.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_tenant.sen -- tenant related words                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" db_tenant.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* the tenant category                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\tenant \\\\category ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the tenant folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Path[].popTenantFolder\n"
    "\n"
    "  Path[].popFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if current folder is ../tenants                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Folder[].isTenants\n"
    "\n"
    "  Folder[] dic.name@ \"tenants\" str.same\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check current folder is ../tenants                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Folder[].checkIsTenants\n"
    "\n"
    "  Folder[].isTenants if true exit then\n"
    "  EC_NOT_IN_TENANTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a tenant folder                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Path[].checkIsTenant ( word )\n"
    "\n"
    "  dup word.category@ find: \\folder equal not if EC_NOT_A_FOLDER false exit then\n"
    "  dup execute dic.kind@ find: \\tenant equal if true exit then\n"
    "  EC_NOT_A_TENANT false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a tenant                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsTenant ( word )\n"
    "  Folder[].findSymbol if true exit then\n"
    "  EC_NOT_A_TENANT false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is not a tenant                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": name::isNotKnownTenant ( word )\n"
    "  Folder[].findSymbol not if true exit then\n"
    "  EC_TENANT_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tenant folder (run by participant)                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :makeTenantFolder params| sTenantNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    sTenantNm \"MAKING TENANT \" swap str.cat \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // make the tenant\n"
    "  sTenantNm folder::makeFolder\n"
    "    find: \\tenant swap execute dic.kind!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // make catalogs folder\n"
    "  sTenantNm :makeCatalogsFolder ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the tenant folder and push it onto task dictionary                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Path[].pushTenantFolder ( \"<tenantName>\" -- )\n"
    "\n"
    "  find execute Path[].pushFolder\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a tenant folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeTenant ( \"<tenantNm>\" --  )\n"
    "\n"
    "  params| sTenantNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "  dup \"REMOVING TENANT \" swap str.cat \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // move to tenant folder\n"
    "  sTenantNm Path[].pushTenantFolder assert\n"
    "\n"
    "  \"catalogs\" folder::remove\n"
    "\n"
    "  Path[].popTenantFolder\n"
    "\n"
    "  sTenantNm folder::remove\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

