    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* meta table related procedures                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\"  start::defProc_Meta\" .verbose\n"
    "\n"
    ": start::defProc_Meta\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // scan tables\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure scanTables\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | metaScan tables | rowToList | output | sink | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // scanTables ;\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* sql compiler related procedures                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\"  start::defProc_SqlCompiler\" .verbose\n"
    "\n"
    ": start::defProc_SqlCompiler\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // sql Compiler\n"
    "  \n"
    "  STD_PATH\n"
    "  \"\n"
    "  procedure sqlCompiler\n"
    "    parameters $sqlStatement\n"
    "\n"
    "  begin\n"
    "\n"
    "    // Where possible, try to name these operators in the format:  <noun><verb>\n"
    "    // e.g. exprValidate\n"
    "    // This makes it easier to glance through and categorise/identify transformations.\n"
    "    // For example, if all transformations of aggregates begin with aggregate or agg\n"
    "    // then it is easy to visually spot them.\n"
    "    // There are always exceptions though, e.g. explainPlan, partitionPlan, etc.\n"
    "\n"
    "    stage stageA on origin :\n"
    "      start\n"
    "      | pulse once\n"
    "// Parsing phase\n"
    "      | parser $sqlStatement\n"
    "// Planning Phase\n"
    "      | nameValidate\n"
    "      | exprValidate\n"
    "      | setOpValidate\n"
    "      | postProject\n"
    "      | exprPushdown\n"
    "      | projValidation\n"
    "// Optimisation Phase\n"
    "      | corrBySquash\n"
    "      | explainPlan\n"
    "      | partitionPlan\n"
    "      | projValidation    // sanity check after partitioning\n"
    "      | partitionExplain\n"
    "// Transliteration Phase\n"
    "      | stageMarkers\n"
    "      | aggregateSplit \n"
    "      | transliterate\n"
    "      | output\n"
    "      | sink\n"
    "      | stageA\n"
    "\n"
    "  end ;\n"
    "  \"\n"
    "  api::addProcedure\n"
    "\n"
    "  // sqlCompiler ;\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* proc: test                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "proc:\n"
    "\n"
    "  procedure scanTables2\n"
    "  begin\n"
    "\n"
    "  stage stageA on origin :\n"
    "    start | pulse once | metaScan tables | rowToList | output | sink | stageA\n"
    "\n"
    "  end\n"
    "  \n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

